/**
 * Change separator for PR branch name
 *
 * @schema MultiEcosystemGroupPullRequestBranchNameSeparator
 */
export enum MultiEcosystemGroupPullRequestBranchNameSeparator {
  /** - */
  VALUE_HYPHEN = '-',
  /** _ */
  VALUE_UNDERSCORE = '_',
  /** / */
  VALUE_FORWARD_SLASH = '/',
}

class DependabotSerializer {
  private constructor() {} // no instances — static-only class

  public static toJsonDependabotProps(
    obj: DependabotProps | undefined,
  ): Record<string, unknown> | undefined {
    if (obj === undefined) {
      return undefined;
    }
    const result: Record<string, unknown> = {
      version: obj.version,
      'enable-beta-ecosystems': obj.enableBetaEcosystems,
      updates: obj.updates?.map((item: any) => this.toJsonUpdate(item)),
      registries: obj.registries,
      'multi-ecosystem-groups':
        obj.multiEcosystemGroups === undefined
          ? undefined
          : Object.fromEntries(
              Object.entries(obj.multiEcosystemGroups).map(
                (entry): [string, unknown] => [
                  entry[0],
                  this.toJsonMultiEcosystemGroup(entry[1]),
                ],
              ),
            ),
    };
    return Object.fromEntries(
      Object.entries(result).filter(([, value]) => value !== undefined),
    );
  }

  public static toJsonUpdate(
    obj: Update | undefined,
  ): Record<string, unknown> | undefined {
    if (obj === undefined) {
      return undefined;
    }
    const result: Record<string, unknown> = {
      allow: obj.allow?.map((item: any) => item),
      assignees: obj.assignees?.map((item: any) => item),
      'commit-message': obj.commitMessage,
      cooldown: obj.cooldown,
      directories: obj.directories?.map((item: any) => item),
      directory: obj.directory,
      'exclude-paths': obj.excludePaths?.map((item: any) => item),
      groups:
        obj.groups === undefined
          ? undefined
          : Object.fromEntries(
              Object.entries(obj.groups).map((entry): [string, unknown] => [
                entry[0],
                entry[1],
              ]),
            ),
      ignore: obj.ignore?.map((item: any) => item),
      'insecure-external-code-execution': obj.insecureExternalCodeExecution,
      labels: obj.labels?.map((item: any) => item),
      milestone: obj.milestone,
      name: obj.name,
      'open-pull-requests-limit': obj.openPullRequestsLimit,
      'package-ecosystem': obj.packageEcosystem,
      'pull-request-branch-name': obj.pullRequestBranchName,
      'rebase-strategy': obj.rebaseStrategy,
      registries: obj.registries,
      schedule: obj.schedule,
      'target-branch': obj.targetBranch,
      vendor: obj.vendor,
      'versioning-strategy': obj.versioningStrategy,
      patterns: obj.patterns?.map((item: any) => item),
      'multi-ecosystem-group': obj.multiEcosystemGroup,
    };
    return Object.fromEntries(
      Object.entries(result).filter(([, value]) => value !== undefined),
    );
  }

  public static toJsonMultiEcosystemGroup(
    obj: MultiEcosystemGroup | undefined,
  ): Record<string, unknown> | undefined {
    if (obj === undefined) {
      return undefined;
    }
    const result: Record<string, unknown> = {
      schedule: obj.schedule,
      labels: obj.labels?.map((item: any) => item),
      assignees: obj.assignees?.map((item: any) => item),
      milestone: obj.milestone,
      'target-branch': obj.targetBranch,
      'commit-message': obj.commitMessage,
      'pull-request-branch-name': obj.pullRequestBranchName,
      'open-pull-requests-limit': obj.openPullRequestsLimit,
      'update-types': obj.updateTypes?.map((item: any) => item),
      'dependency-type': obj.dependencyType,
      'exclude-patterns': obj.excludePatterns?.map((item: any) => item),
    };
    return Object.fromEntries(
      Object.entries(result).filter(([, value]) => value !== undefined),
    );
  }
}

export class Dependabot extends Resource {
  public readonly resourceType = 'Dependabot';
  public readonly apiVersion = 'github.cdk-x.com/v1';

  constructor(
    scope: Construct,
    id: string,
    public readonly props: DependabotProps,
  ) {
    super(scope, id);
  }

  protected toProperties(): Record<string, unknown> {
    return DependabotSerializer.toJsonDependabotProps(this.props) ?? {};
  }
}
